checkpoints.source:
nui 1
style Ink {
 width: 2px,
 color: #123456,
}
style Red {
 width: 2px,
 color: #aa5612,
}
profile Draft
profile Cut
style Detail {
 width: 2px,
 color: #123456,
 for @Cut {
  visible: false,
 }
}
const points: point[] = [(2, 5)]
const mapped: point[] = for pt in @points { coordinate(x: @pt.x + 7, y: @pt.y - 3) }
group Piece {
 point Origin = coordinate(x: 3, y: -5)
 for pt in @mapped {
  point Mark = from(source: @pt)
  line Derived [Ink] = segment(start: @pt, end: (41, 29))
 }
 line Selected [Red] = segment(start: @mapped[0], end: (47, 31))
}
group Control {
 point Ignored = coordinate(x: -1000, y: -2000)
 line Calibration [Ink] = segment(start: (-107, -31), end: (-7, -31))
 line Sibling [Red] = segment(start: (2, -11), end: (5, -7))
}
group Unselected {
 line Outside [Ink] = segment(start: (5000, 5000), end: (5100, 5000))
}
layout Pattern {
 place @Piece(at: (0, 0), scale: 1, angle: 0, mirror: false)
 place @Control(at: (0, 0), scale: 1, angle: 0, mirror: false)
}
svg Vector(layout: @Pattern, profile: @Draft, margin: 3)
print Paper(layout: @Pattern, profile: @Draft, paper: a4, orientation: portrait, overlap: 10)

